corporate_design.toad_component_blueprint:
canvas {
  size: 900px 560px;
  fill: #F0F9FF;
  font-family: "Montserrat, sans-serif";
}

>blue = #0284C7;
>navy = #0F172A;

rect #ferryCard {
  at: center of canvas;
  size: 800px 460px;
  fill: #FFFFFF;
  stroke: >blue;
  stroke-width: 1px;
  radius: 10px;
}

text #ferryHeader {
  at: top left of #ferryCard offset 36px 36px;
  content: "NORDIC FERRY LINES // ZERO-EMISSION FLEET";
  font-size: 13px;
  font-weight: 700;
  color: >blue;
}

text #ferryTitle {
  at: below #ferryHeader offset 16px;
  content: "Täglich lautlos durch die Schären – mit Batterieantrieb";
  font-size: 28px;
  font-weight: 700;
  color: >navy;
}
